<?php require_once __DIR__ . '/../../includes/layout.php'; require_login(); check_csrf(); if($_SERVER['REQUEST_METHOD']==='POST'){foreach(rows('SELECT id FROM students') as $s) generate_prediction((int)$s['id']); set_flash('success','Predictive analytics regenerated.'); redirect('predictive.php');} $data=rows('SELECT p.*,s.student_no,u.full_name FROM predictions p JOIN students s ON s.id=p.student_id JOIN users u ON u.id=s.user_id WHERE p.id IN (SELECT MAX(id) FROM predictions GROUP BY student_id) ORDER BY p.risk_score DESC'); render_header('Predictive Analytics'); ?><div class="page-title"><div><h1>Predictive Analytics</h1><p>Simulated AI logic: if attendance &lt; 75% and GPA &lt; 2.5 then risk is high.</p></div><form method="post"><?= csrf_field() ?><button class="btn btn-primary"><i class="fa-solid fa-rotate me-2"></i>Regenerate</button></form></div><div class="row g-4"><div class="col-lg-4"><div class="panel"><div class="panel-title">Risk Distribution</div><canvas id="riskDist" height="200"></canvas></div></div><div class="col-lg-8"><div class="panel"><div class="panel-title">Performance Trend</div><canvas id="trend" height="95"></canvas></div></div></div><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Attendance</th><th>GPA</th><th>Risk Score</th><th>Grade Prediction</th><th>Dropout Probability</th><th>Risk Level</th></tr></thead><tbody><?php foreach($data as $p): ?><tr><td><strong><?= e($p['full_name']) ?></strong><br><small><?= e($p['student_no']) ?></small></td><td><?= e($p['attendance_rate']) ?>%</td><td><?= e($p['gpa']) ?></td><td><?= e($p['risk_score']) ?>/100</td><td><?= e($p['grade_prediction']) ?></td><td><?= e($p['dropout_probability']) ?>%</td><td><span class="badge-soft risk-<?= e($p['risk_level']) ?>"><?= e($p['risk_level']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><script>document.addEventListener('DOMContentLoaded',()=>{makeDoughnut('riskDist',['High','Medium','Low'],[<?= scalar("SELECT COUNT(*) FROM students WHERE risk_level='High'") ?>,<?= scalar("SELECT COUNT(*) FROM students WHERE risk_level='Medium'") ?>,<?= scalar("SELECT COUNT(*) FROM students WHERE risk_level='Low'") ?>]);makeLineChart('trend',['Jan','Feb','Mar','Apr','May','Jun'],[78,84,81,82,76,85],'Performance')});</script><?php render_footer(); ?>
